import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useLocalSearchParams, useRouter } from 'expo-router';
import {
  ActivityIndicator,
  Image,
  Modal,
  PanResponder,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';

import { ApiLittleShipData, fetchKnownShips, fetchLittleShip } from '@/services/publicApi';

function readField(fields: Record<string, unknown>, key: string) {
  const value = fields[key];
  if (value === null || value === undefined) return null;
  const str = String(value).trim();
  return str.length > 0 ? str : null;
}

function readFieldCandidates(fields: Record<string, unknown>, candidates: string[]) {
  for (const key of candidates) {
    const exact = readField(fields, key);
    if (exact) return exact;
  }

  const normalized = new Map<string, string>();
  Object.keys(fields).forEach((key) => normalized.set(key.trim().toLowerCase(), key));

  for (const candidate of candidates) {
    const match = normalized.get(candidate.trim().toLowerCase());
    if (!match) continue;
    const value = readField(fields, match);
    if (value) return value;
  }

  return null;
}

function readShipCandidates(ship: Record<string, unknown> | null | undefined, candidates: string[]) {
  if (!ship) return null;

  for (const key of candidates) {
    const value = ship[key];
    if (value === null || value === undefined) continue;
    const str = String(value).trim();
    if (str.length > 0) return str;
  }

  return null;
}

function formatPresenceValue(value: string | null) {
  if (!value) return '-';
  const normalized = value.trim().toLowerCase();
  if (['true', 'yes', 'y', '1', 'present', 'included', 'in list', '✓'].includes(normalized)) {
    return '✓';
  }
  if (['false', 'no', 'n', '0', 'absent', 'not present', '✗', 'x'].includes(normalized)) {
    return '✗';
  }
  return value;
}

function isAffirmative(value: string | null) {
  if (!value) return false;
  return ['true', 'yes', 'y', '1', 'present', 'included', 'in list', '✓'].includes(value.trim().toLowerCase());
}

export default function LittleShipDetailScreen() {
  const router = useRouter();
  const params = useLocalSearchParams<{ ship?: string | string[] }>();
  const slugParam = params.ship;
  const slug = Array.isArray(slugParam) ? slugParam[0] : slugParam;

  const [data, setData] = useState<ApiLittleShipData | null>(null);
  const [orderedShipSlugs, setOrderedShipSlugs] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [previewImageUrl, setPreviewImageUrl] = useState<string | null>(null);
  const isTouchingHeroGalleryRef = useRef(false);

  useEffect(() => {
    let mounted = true;

    (async () => {
      try {
        const response = await fetchKnownShips();
        if (!mounted) return;
        const sorted = response.rows
          .filter(
            (row) => typeof row.slug === 'string' && row.slug.trim().length > 0 && row.has_narrative === true,
          )
          .sort((a, b) =>
            (a.display_name || a.ship_name).localeCompare(b.display_name || b.ship_name, undefined, {
              sensitivity: 'base',
            }),
          )
          .map((row) => String(row.slug));
        setOrderedShipSlugs([...new Set(sorted)]);
      } catch {
        if (!mounted) return;
        setOrderedShipSlugs([]);
      }
    })();

    return () => {
      mounted = false;
    };
  }, []);

  useEffect(() => {
    if (!slug) {
      setError('Missing ship slug.');
      setIsLoading(false);
      return;
    }

    let mounted = true;

    (async () => {
      try {
        const response = await fetchLittleShip(slug);
        if (!mounted) return;
        setData(response.data);
      } catch {
        if (!mounted) return;
        setError('Unable to load little ship details .');
      } finally {
        if (mounted) setIsLoading(false);
      }
    })();

    return () => {
      mounted = false;
    };
  }, [slug]);

  const title = useMemo(() => {
    if (!data) return 'Little Ship';
    return (
      readField(data.fields, 'Ship Name') ||
      (typeof data.ship?.ship_name === 'string' ? data.ship.ship_name : null) ||
      data.slug ||
      'Little Ship'
    );
  }, [data]);

  const operations = data ? readField(data.fields, 'Operations Used') : null;
  const shipType = data ? readField(data.fields, 'Ship Type') : null;
  const member = data ? readField(data.fields, 'ADLS Member') : null;
  const isAdlsMember = isAffirmative(member);
  const returnStatus = data
    ? readField(data.fields, 'Return Status') ||
      (typeof data.ship?.return_status === 'string' ? data.ship.return_status : null)
    : null;

  const summaryPairs = data
    ? [
        ['ADLS ID', readField(data.fields, 'ADLS ID')],
        ['Builder', readField(data.fields, 'Builder')],
        ['Build Year', readField(data.fields, 'Build Year')],
        ['Length', readField(data.fields, 'Length')],
        ['Beam', readField(data.fields, 'Beam')],
        ['Draft', readField(data.fields, 'Draft')],
        ['Displacement', readField(data.fields, 'Displacement')],
        ['Construction', readField(data.fields, 'Construction')],
        ['Engine', readField(data.fields, 'Engine')],
      ].filter((item) => item[1])
    : [];
  const summaryRows = useMemo(() => {
    const rows: [string, string | null, string, string | null][] = [];
    for (let i = 0; i < summaryPairs.length; i += 2) {
      const left = summaryPairs[i];
      const right = summaryPairs[i + 1];
      rows.push([
        left?.[0] ?? '',
        (left?.[1] as string | null) ?? null,
        right?.[0] ?? '',
        (right?.[1] as string | null) ?? null,
      ]);
    }
    return rows;
  }, [summaryPairs]);

  const historyText = data
    ? (typeof data.ship?.ship_history === 'string' ? data.ship.ship_history : null) ||
      (typeof data.ship?.narrative === 'string' ? data.ship.narrative : null)
    : null;
  const redListPresence = data
    ? formatPresenceValue(
        readFieldCandidates(data.fields, ['Present in Red List', 'Red List']) ??
          readShipCandidates(data.ship, ['present_in_red_list', 'red_list']),
      )
    : '-';
  const ordeReportPresence = data
    ? formatPresenceValue(
        readFieldCandidates(data.fields, ['Present in Orde Report', 'Orde Report']) ??
          readShipCandidates(data.ship, ['present_in_orde_report', 'orde_report']),
      )
    : '-';
  const smallCraftPresence = data
    ? formatPresenceValue(
        readFieldCandidates(data.fields, [
          'Present in Small Craft Service List',
          'Small Craft Service List',
          'Small Craft List',
        ]) ?? readShipCandidates(data.ship, ['present_in_small_craft_service_list', 'small_craft_service_list']),
      )
    : '-';
  const researchDisclaimer =
    '*This infomation may be subject to errors or omissions in research and is provided by the 3rd party research website https://www.operationdynamo.navy, presence in the Orde Report includes a narrative, Orde may have references to the ship not participating but other evidence may contradict this.\n' +
    'Inclusion in the lists above does not necasarily refer to this ship, some ships had duplicate names and further research should be conducted. The records contained on this page may contain ancedotal or 3rd party narrative or evidence.';
  const currentShipIndex = useMemo(() => {
    if (!slug) return -1;
    return orderedShipSlugs.indexOf(slug);
  }, [orderedShipSlugs, slug]);
  const previousShipSlug = currentShipIndex > 0 ? orderedShipSlugs[currentShipIndex - 1] : null;
  const nextShipSlug =
    currentShipIndex >= 0 && currentShipIndex < orderedShipSlugs.length - 1
      ? orderedShipSlugs[currentShipIndex + 1]
      : null;

  const navigateToAdjacentShip = useCallback(
    (direction: 'prev' | 'next') => {
      const target = direction === 'next' ? nextShipSlug : previousShipSlug;
      if (!target) return;
      setPreviewImageUrl(null);
      router.replace(`/history/little-ship/${target}`);
    },
    [nextShipSlug, previousShipSlug, router],
  );

  const swipeResponder = useMemo(
    () =>
      PanResponder.create({
        onMoveShouldSetPanResponder: (_, gestureState) =>
          !isTouchingHeroGalleryRef.current &&
          Math.abs(gestureState.dx) > 20 &&
          Math.abs(gestureState.dx) > Math.abs(gestureState.dy) * 1.2,
        onPanResponderRelease: (_, gestureState) => {
          if (isTouchingHeroGalleryRef.current) return;
          if (gestureState.dx <= -70) {
            navigateToAdjacentShip('next');
            return;
          }
          if (gestureState.dx >= 70) {
            navigateToAdjacentShip('prev');
          }
        },
      }),
    [navigateToAdjacentShip],
  );

  return (
    <ScrollView contentContainerStyle={styles.container} {...swipeResponder.panHandlers}>
      {isLoading ? <ActivityIndicator size="small" color="#0E4A72" /> : null}
      {error ? <Text style={styles.errorText}>{error}</Text> : null}

      {data ? (
        <>
          <View style={styles.topRow}>
            <Text style={styles.title}>{title}</Text>
          </View>

          <View style={styles.badgesWrap}>
            {shipType ? <Text style={styles.badge}>{shipType}</Text> : null}
            {operations ? <Text style={styles.badge}>{operations}</Text> : null}
            {member ? (
              <Text style={[styles.badge, isAdlsMember ? styles.memberBadge : styles.nonMemberBadge]}>
                {`ADLS Member: ${member}`}
              </Text>
            ) : null}
            {returnStatus ? <Text style={[styles.badge, styles.returnBadge]}>{`Status: ${returnStatus}`}</Text> : null}
          </View>

          <View style={styles.swipeHintCard}>
            <Text style={styles.swipeHintText}>
              Swipe left/right to browse ships
              {previousShipSlug || nextShipSlug
                ? ` (${previousShipSlug ? '← previous' : ''}${previousShipSlug && nextShipSlug ? ' • ' : ''}${
                    nextShipSlug ? 'next →' : ''
                  })`
                : ''}
            </Text>
          </View>

          {data.images.length > 0 ? (
            <ScrollView
              horizontal
              showsHorizontalScrollIndicator={false}
              contentContainerStyle={styles.imageRow}
              onTouchStart={() => {
                isTouchingHeroGalleryRef.current = true;
              }}
              onTouchEnd={() => {
                isTouchingHeroGalleryRef.current = false;
              }}
              onTouchCancel={() => {
                isTouchingHeroGalleryRef.current = false;
              }}>
              {data.images.map((imageUrl) => (
                <Image key={imageUrl} source={{ uri: imageUrl }} style={styles.heroImage} />
              ))}
            </ScrollView>
          ) : null}

          {summaryPairs.length > 0 ? (
            <View style={styles.card}>
              <Text style={styles.sectionTitle}>Ship Details</Text>
              {summaryRows.map(([labelA, valueA, labelB, valueB], idx) => (
                <View key={`${labelA}-${labelB}-${idx}`} style={styles.detailRow}>
                  <View style={styles.detailColumn}>
                    <Text style={styles.detailLabel}>{labelA}</Text>
                    <Text style={styles.detailValue}>{valueA ?? '-'}</Text>
                  </View>
                  <View style={styles.detailColumn}>
                    <Text style={styles.detailLabel}>{labelB || '-'}</Text>
                    <Text style={styles.detailValue}>{valueB ?? '-'}</Text>
                  </View>
                </View>
              ))}
            </View>
          ) : null}

          <View style={styles.card}>
            <Text style={styles.sectionTitle}>Research Lists</Text>
            <View style={styles.listTableHeader}>
              <Text style={styles.listTableHeaderCell}>Present in Red List</Text>
              <Text style={styles.listTableHeaderCell}>Present in Orde Report</Text>
              <Text style={styles.listTableHeaderCell}>Present in Small Craft Service List</Text>
            </View>
            <View style={styles.listTableValueRow}>
              <Text style={[styles.listTableValueCell, redListPresence === '✓' ? styles.listTickValueCell : null]}>
                {redListPresence}
              </Text>
              <Text style={[styles.listTableValueCell, ordeReportPresence === '✓' ? styles.listTickValueCell : null]}>
                {ordeReportPresence}
              </Text>
              <Text style={[styles.listTableValueCell, smallCraftPresence === '✓' ? styles.listTickValueCell : null]}>
                {smallCraftPresence}
              </Text>
            </View>
            <Text style={styles.disclaimerText}>{researchDisclaimer}</Text>
          </View>

          {data.images.length > 0 ? (
            <View style={styles.card}>
              <Text style={styles.sectionTitle}>Gallery</Text>
              <View style={styles.galleryGrid}>
                {data.images.map((imageUrl) => (
                  <Pressable key={imageUrl} onPress={() => setPreviewImageUrl(imageUrl)}>
                    <Image source={{ uri: imageUrl }} style={styles.galleryImage} />
                  </Pressable>
                ))}
              </View>
            </View>
          ) : null}

          {historyText ? (
            <View style={styles.card}>
              <Text style={styles.sectionTitle}>History</Text>
              <Text style={styles.historyText}>{historyText}</Text>
            </View>
          ) : null}

          <View style={styles.card}>
            <Text style={styles.sectionTitle}>Restoration Albums</Text>
            <Text style={styles.historyText}>No restoration images hae been uploaded for this vessel</Text>
          </View>

          <View style={styles.card}>
            <Text style={styles.sectionTitle}>Crew</Text>
            <Text style={styles.historyText}>
              This Little Ships Captain has not updated their crew list or decided not to make it public
            </Text>
          </View>

          <View style={styles.card}>
            <Text style={styles.sectionTitle}>Journal</Text>
            <Text style={styles.historyText}>This ship has no journal entries</Text>
          </View>

          <View style={styles.card}>
            <Text style={styles.sectionTitle}>Media and Journals</Text>
            <Text style={styles.historyText}>
              this owner has not uploaded any Media, Journal References or Links.
            </Text>
            <Text style={styles.disclaimerText}>
              Some information on this page may be curated by third parties or owners; if you believe any content
              gives rise to copyright or related legal concerns, please contact us in the first instance so that the
              matter can be reviewed and addressed appropriately.
            </Text>
          </View>
        </>
      ) : null}

      <Modal
        animationType="fade"
        visible={Boolean(previewImageUrl)}
        onRequestClose={() => setPreviewImageUrl(null)}
        transparent>
        <View style={styles.previewOverlay}>
          <Pressable style={styles.previewBackdrop} onPress={() => setPreviewImageUrl(null)} />
          <View style={styles.previewCard}>
            <Pressable style={styles.previewClose} onPress={() => setPreviewImageUrl(null)}>
              <Text style={styles.previewCloseText}>X</Text>
            </Pressable>
            {previewImageUrl ? (
              <Image source={{ uri: previewImageUrl }} style={styles.previewImage} resizeMode="contain" />
            ) : null}
          </View>
        </View>
      </Modal>
    </ScrollView>
  );
}

